/*
 * arch/m68k/sau2/iodefs.s - the SAU2 map's absolute symbols, as link-time
 * symbols
 *
 * Generated by: Claude Opus 5.5
 *
 * The binder resolved COLD's and DUMP's references to the I/O pages and
 * to the PTT/PROT windows through absolute symbols (the map's IODEFS
 * module, and the zero-size PTT, PROT and TRAP_PAGE segments), which is
 * why those operand cells are in its fixup table (RELOC; docs/
 * rfc-cold-start.md section 5 step 8).  cold/sau2/cold_start.s and
 * dump/sau2/dump.s reference them by name, so each such cell is an
 * R_68K_32 relocation a fixup generator finds (bead source-gfn1); this
 * object defines them, once, as absolute globals.  It has no bytes.
 *
 * The values are the SAU2's (hardware addresses are per-SAU: the C names
 * are in arch/m68k/sau2/hw.h, and the PROT boundary is svc/svc.h's
 * SVC_USER_SPACE_LIMIT).  The kernel's C still uses the hw.h literals;
 * only the hand-written cold-start code links against these.  The C
 * headers are the source of truth: tools/check_iodefs.py (`make
 * check-iodefs', part of `make check') fails if a value here differs from
 * the C macro named in its comment.
 *
 *   D52  F4FC00  IODEFS_GUARD       loaded at 25DF1A, size = 0
 *        FC0000  DISP1_MEM / IODEFS   ...   FFB400  MMU    FFB800  PFT
 *   D54  700000  PTT                loaded at 700000, size = 0
 *        CC0000  PROT
 *   D37       0  TRAP_PAGE          loaded at 0, size = 400
 */

        .globl  TRAP_PAGE
        .globl  PTT
        .globl  PROT
        .globl  DISP1_MEM
        .globl  DISP1
        .globl  RING2
        .globl  DMA
        .globl  DISK
        .globl  TIMR
        .globl  SIO
        .globl  MMU
        .globl  PFT

        .equ    TRAP_PAGE,  0x00000000  /* the exception vector page (VBR) */
        .equ    PTT,        0x00700000  /* page translation table window (SAU2_PTT_BASE) */
        .equ    PROT,       0x00CC0000  /* the PROT window (SVC_USER_SPACE_LIMIT, svc/svc.h: user space ends here); the 68020 fixups move it to 0x3AC0000 */
        .equ    DISP1_MEM,  0x00FC0000  /* display memory (SAU2_DISPLAY_MEM_BASE); also IODEFS */
        .equ    DISP1,      0x00FF9800  /* display controller (SAU2_DISPLAY_CTRL_REGS) */
        .equ    RING2,      0x00FF9C00  /* token ring controller (SAU2_RING2_BASE) */
        .equ    DMA,        0x00FFA000  /* DMA controller (SAU2_DMAC_BASE) */
        .equ    DISK,       0x00FFA800  /* disk / floppy / calendar page (SAU2_DISK_BASE, SAU2_CALENDAR_BASE) */
        .equ    TIMR,       0x00FFAC00  /* timer (SAU2_TIMER_BASE) */
        .equ    SIO,        0x00FFB000  /* serial I/O (SAU2_SIO_BASE) */
        .equ    MMU,        0x00FFB400  /* MMU registers (SAU2_MMU_REGS) */
        .equ    PFT,        0x00FFB800  /* page frame table (SAU2_PFT_BASE) */
